using System;namespace LWS.TruckSkeeBall.Editor {public static class SkeeFixtures {public static int Run(){int checks=0;void Check(bool ok,string message){checks++;if(!ok)throw new Exception("Skee fixture: "+message);}var r=new SkeeRules();r.Reset(1);for(int i=1;i<=9;i++){Check(r.Lock(0,i,10),"nine actual delivery IDs accepted");Check(!r.Lock(0,i,100),"duplicate delivery cannot award twice");Check(i==9?r.Complete:!r.Complete,"solo completes after exactly nine");}Check(r.Winner==0&&r.totals[0]==90&&!r.CanLaunch(0),"solo score/no tenth delivery");r.Reset(2);for(int i=1;i<=9;i++)Check(r.Lock(0,i,20),"independent fast lane advances without slower lane");Check(!r.Complete&&!r.CanLaunch(0)&&r.CanLaunch(1),"early finisher waits without stealing extra attempt");for(int i=1;i<=9;i++)r.Lock(1,i,20);Check(r.ExtraRound==1&&r.required[0]==10&&r.required[1]==10,"tied leaders both receive tenth launch");Check(r.Lock(0,10,100)&&!r.Complete,"first extra cannot prematurely end match");Check(r.Lock(1,10,0)&&r.Winner==0&&r.Complete,"equal extra opportunity then winner");Check(r.totals[0]==280&&r.totals[1]==180,"authoritative totals preserved");Check(!r.Lock(1,11,100),"post-match awards rejected");r.Reset(3);for(int i=1;i<=9;i++){r.Lock(0,i,50);r.Lock(1,i,50);r.Lock(2,i,10);}Check(r.Eligible==3&&!r.CanLaunch(2)&&r.CanLaunch(0)&&r.CanLaunch(1),"only tied leaders receive extras");bool rejected=false;try{r.Lock(0,10,17);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected&&r.attempts[0]==9,"invalid points cannot change attempt count");r.Reset(8);Check(r.Count==8&&r.Eligible==255&&Array.TrueForAll(r.attempts,n=>n==0),"eight-player hot-seat reset");for(int i=1;i<=9;i++)for(int seat=7;seat>=0;seat--)r.Lock(seat,i,seat==7?30:10);Check(r.Winner==7&&r.totals[7]==270&&Array.TrueForAll(r.attempts,n=>n==9),"eight participants all complete nine before winner");return checks;}}}
